"""Contact sheet for substitute teachers."""

from typing import Iterable, List, Sequence, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _cells(student: Student) -> Tuple[str, str, str]:
    if not student.email:
        raise ProjectError(f"no email for student: {student.display_name}")
    return (student.display_name, student.section, student.email)


def _pad(cells: Sequence[str], widths: Sequence[int]) -> str:
    padded = [text.ljust(width) for text, width in zip(cells, widths)]
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Text rows of name, section and email in columns, sorted by name."""
    ordered = sorted(students, key=lambda student: student.display_name)
    if not ordered:
        raise ProjectError("no students to put on the contact sheet")
    table = [_cells(student) for student in ordered]
    widths = [max(len(cells[index]) for cells in table) for index in range(3)]
    return [_pad(cells, widths) for cells in table]
